        toggle("Remind me when it’s my turn","A nudge when your partner shares.",Vault.prefs(this).getBoolean("turn_reminders",true),enabled->{Vault.prefs(this).edit().putBoolean("turn_reminders",enabled).apply();if(enabled)notifications();Notify.onState(this,SyncEngine.state(this),SyncEngine.state(this),false);});
